#include <iostream>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 modPow(int64 base, int64 exponent, int64 modulus) {
    if (modulus == 1) return 0;

    base %= modulus;
    if (base < 0) base += modulus;

    int64 result = 1 % modulus;
    while (exponent > 0) {
        if (exponent & 1)
            result = static_cast<int64>((i128)result * base % modulus);
        base = static_cast<int64>((i128)base * base % modulus);
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, x;
    cin >> n >> x;

    const int64 exponent = n;
    const int64 modulus = n + 1;

    for (int64 i = x - 1; i >= 2; --i) {
        if (modPow(i, exponent, modulus) == 1 &&
            (i - 1) % modulus != 0) {
            cout << i;
            return 0;
        }
    }

    cout << -1;
    return 0;
}

